1978	func sourceMaterializationDiffers(root, commit string, entries []ReviewBundleSubjectEntry) string {
1979		if commit == "" || !hasGitMetadata(root) {
1980			// No sealed commit, or no repository at all: nothing to compare with (a dispatch has both).
1981			return ""
1982		}
1983		checkedDirs := map[string]bool{}
1984		for _, entry := range entries {
1985			if entry.Class == "submodule" {
1986				continue
1987			}
1988			// The absence the bundle sealed is part of what it reviewed: a removed path, and the old
1989			// side of a rename, must still be absent, whatever Git was told to ignore.
1990			for _, gone := range removedSides(entry) {
1991				if _, err := os.Lstat(filepath.Join(root, filepath.FromSlash(gone))); err == nil {
1992					return gone + " (the bundle sealed it as removed, and it is there)"
1993				}
1994			}
1995			if entry.Action == "removed" {
1996				continue
1997			}
1998			rel := reviewBundleEntryPath(entry)
1999			if linkAbove(root, rel, checkedDirs) {
2000				return rel + " (a directory above it is a link, or not a directory)"
2001			}
2002			out, err := gitCommand("-C", root, "ls-tree", "-z", commit, "--", rel).Output()
2003			if err != nil {
2004				return rel + " (its record in the sealed commit could not be read: " + err.Error() + ")"
2005			}
2006			meta, _, ok := strings.Cut(strings.TrimSuffix(string(out), "\x00"), "\t")
2007			fields := strings.Fields(meta)
2008			if !ok || len(fields) < 3 {
2009				continue // not in the sealed commit
2010			}
2011			mode, object := fields[0], fields[2]
2012			info, lerr := os.Lstat(filepath.Join(root, filepath.FromSlash(rel)))
2013			if lerr != nil {
2014				return rel + " (it cannot be inspected: " + lerr.Error() + ")"
2015			}
2016			switch mode {
2017			case "120000":
2018				target, rerr := os.Readlink(filepath.Join(root, filepath.FromSlash(rel)))
2019				if info.Mode()&os.ModeSymlink == 0 || rerr != nil || gitBlobID("sha1", []byte(target)) != object && gitBlobID("sha256", []byte(target)) != object {
2020					return rel + " (it is not the link the sealed commit records)"
2021				}
2022			default:
2023				if !info.Mode().IsRegular() {
2024					return rel + " (it is not a regular file, and the sealed commit records one)"
2025				}
2026				if runtime.GOOS != "windows" && (info.Mode().Perm()&0o111 != 0) != (mode == "100755") {
2027					return rel + " (its executable bit differs)"
2028				}
2029			}
2030		}
2031		return ""
2032	}
