2037	// reviewRunRuntimeDir creates the private directory of one run. Every run of
2038	// an attempt uses the same path, so a resumed reviewer session, which still
2039	// refers to the sealed checkout it worked in, finds the checkout recreated
2040	// there after the interrupted run removed it (spec
2041	// pose-review-resume-keeps-the-sealed-checkout R1). The directory is created
2042	// exclusively and never followed: when the path already exists, from an
2043	// unfinished cleanup or from someone else, the run fails instead of sharing
2044	// it. A run without an attempt keeps a random name.
2045	func reviewRunRuntimeDir(attemptID string) (string, error) {
2046		if !reviewAttemptIDRE.MatchString(attemptID) {
2047			return os.MkdirTemp("", "pose-review-run-*")
2048		}
2049		dir := filepath.Join(os.TempDir(), "pose-review-run-"+attemptID[len("rat-"):len("rat-")+32])
2050		if err := os.Mkdir(dir, 0o700); err != nil {
2051			if errors.Is(err, fs.ErrExist) {
2052				return "", fmt.Errorf("the attempt's runtime directory %s already exists; an earlier run of the attempt did not clean up, or another process holds the path", dir)
2053			}
2054			return "", err
2055		}
2056		return dir, nil
2057	}
