720		paths := []string{}
721		var total int64
722		err := fs.WalkDir(root.FS(), ".", func(path string, d fs.DirEntry, err error) error {
723			if err != nil {
724				return err
725			}
726			if path == "." {
727				return nil
728			}
729			if len(paths) >= maxFiles || strings.Count(path, "/") > 128 {
730				return fmt.Errorf("cleanup inventory exceeds coverage")
731			}
732			info, err := d.Info()
733			if err != nil {
734				return err
735			}
736			if info.Mode().IsRegular() {
737				total += info.Size()
