739					return fmt.Errorf("cleanup inventory exceeds bytes")
740				}
741			}
742			paths = append(paths, path)
743			return nil
744		})
745		if err != nil {
746			return fmt.Errorf("runtime cleanup inventory incomplete; resources retained")
747		}
748		for i := len(paths) - 1; i >= 0; i-- {
749			if err := root.Remove(paths[i]); err != nil && !errors.Is(err, os.ErrNotExist) {
750				return fmt.Errorf("runtime cleanup incomplete; resources retained")
751			}
752		}
753		return nil
754	}
