460	// ReviewResumeDelay computes a bounded, non-polling wait; callers revalidate afterwards.
461	func ReviewResumeDelay(r ReviewRun, now time.Time, max time.Duration, jitter time.Duration) (time.Duration, error) {
462		if r.Interruption == nil || r.Interruption.ResetAt == "" {
463			return 0, fmt.Errorf("no recorded reset instant")
464		}
465		if max <= 0 || max > 24*time.Hour || jitter < 0 || jitter > time.Second {
466			return 0, fmt.Errorf("wait bound must be positive and at most 24h; jitter at most 1s")
467		}
468		reset, e := time.Parse(time.RFC3339Nano, r.Interruption.ResetAt)
469		if e != nil {
470			return 0, e
471		}
472		delay := reset.Sub(now)
473		if delay < 0 {
474			delay = 0
475		}
476		delay += jitter
