188	func (s Store) recordedAttemptRun(a DelegatedReviewAttempt, own string) (ReviewRun, bool, error) {
189		runs, lost, err := s.ReadReviewRuns(a.BundleID)
190		if err != nil {
191			return ReviewRun{}, false, err
192		}
193		if lost = withoutOwnWitness(lost, own); len(lost) > 0 {
194			// An unreadable run may be this release's: the history is unknown,
195			// and the release does not write another (review round 4, N3).
196			return ReviewRun{}, false, fmt.Errorf("the run history of %s is incomplete, so an earlier release cannot be ruled out: %s", a.BundleID, strings.Join(lost, "; "))
197		}
198		var latest *ReviewRun
199		for i := range runs {
200			if runs[i].AttemptID == a.AttemptID && (latest == nil || runs[i].EndedAt > latest.EndedAt) {
201				latest = &runs[i]
202			}
203		}
204		if latest == nil {
205			return ReviewRun{}, false, nil
206		}
207		return *latest, true, nil
208	}
